(()=>{'use strict';
const C=FLOWER_CONTENT,M=BouquetModel,$=s=>document.querySelector(s),canvas=$('#bouquet'),ctx=canvas.getContext('2d');
let state=M.create(),history=[],active='flowers',uid=0,drag=null,pdfUrl=null,pdfFile=null,shareMessage='';
const flowers=new Image(),wraps=new Image();flowers.src='assets/flowers-cutout.png';wraps.src='assets/wraps.png';
const products=new Map(C.products.map(p=>[p.id,p]));
function remember(){history.push(structuredClone(state));if(history.length>40)history.shift()}
function notify(text){$('#feedback').textContent=text;$('#atelier-feedback').textContent=text}
function add(id){if(state.stems.length>=M.MAX){notify('Bu tasarımda en fazla '+M.MAX+' dal kullanabilirsin. Bir dalı çıkarıp yenisini ekleyebilirsin.');return}remember();M.add(state,id,'s'+(++uid));$('#stage-caption').textContent='Çiçeğe dokun. Sürükle. Kendi dokunuşunu kat.';notify('');refresh()}
function remove(id){remember();M.remove(state,id);refresh()}
function cropFlower(context,p,x,y,w,h){if(!flowers.complete||!flowers.naturalWidth)return;let sw=flowers.naturalWidth/4,sh=flowers.naturalHeight/2;context.drawImage(flowers,p.cell%4*sw,Math.floor(p.cell/4)*sh,sw,sh,x,y,w,h)}
function draw(target=ctx,selection=true){target.clearRect(0,0,1000,1000);const hero=target.canvas.id==='hero-bouquet';const grad=target.createRadialGradient(500,480,10,500,500,700);if(!hero){grad.addColorStop(0,'#faf8f2');grad.addColorStop(1,'#eeece3');target.fillStyle=grad;target.fillRect(0,0,1000,1000);}
 target.save();target.fillStyle='#4e3a2a10';target.beginPath();target.ellipse(510,965,145,13,0,0,Math.PI*2);target.fill();target.restore();
 const wrapReady=wraps.complete&&wraps.naturalWidth;
 const wrapRect={x:282,y:347,w:436,h:654};
 function paper(front){if(!wrapReady)return;const w=wrapRect;target.save();if(front){target.beginPath();target.moveTo(w.x,w.y+w.h*.19);target.lineTo(w.x+w.w*.5,w.y+w.h*.44);target.lineTo(w.x+w.w,w.y+w.h*.18);target.lineTo(w.x+w.w,w.y+w.h);target.lineTo(w.x,w.y+w.h);target.closePath();target.clip()}const sw=wraps.naturalWidth/3;target.drawImage(wraps,C.wraps[state.wrap].cell*sw,0,sw,wraps.naturalHeight,w.x,w.y,w.w,w.h);target.restore()}
 paper(false);
 for(const s of [...state.stems].sort((a,b)=>(a.depth||0)-(b.depth||0))){const p=products.get(s.product);const size=p.category==='green'?460:p.category==='accents'?390:p.id==='lily'?410:350;target.save();target.translate(s.x,s.y);target.rotate(s.angle*Math.PI/180);cropFlower(target,p,-size*.375,-s.height*.82-size*.18,size*.75,size);target.restore()}
 paper(true);

 if(selection){const s=state.stems.find(s=>s.id===state.selected);if(s){let p=head(s);target.save();target.strokeStyle='#742e46';target.lineWidth=1.6;const r=60,l=13;target.beginPath();for(const [dx,dy] of [[-1,-1],[1,-1],[-1,1],[1,1]]){const x=p.x+dx*r,y=p.y+dy*r;target.moveTo(x-dx*l,y);target.lineTo(x,y);target.lineTo(x,y-dy*l)}target.stroke();target.restore()}}
}
function head(s){let r=s.angle*Math.PI/180,d=s.height*.82;return{x:s.x+Math.sin(r)*d,y:s.y-Math.cos(r)*d}}
function catalog(){const counts=new Map(M.summary(state,C.products).map(p=>[p.id,p.count]));$('#catalog').replaceChildren();for(const p of C.products.filter(p=>p.category===active)){const card=document.createElement('article');card.className='product-card';const art=document.createElement('div');art.className='product-art';const pic=document.createElement('canvas');pic.width=150;pic.height=200;pic.setAttribute('role','img');pic.setAttribute('aria-label',p.name+' — temsili çiçek görseli');cropFlower(pic.getContext('2d'),p,0,0,150,200);art.append(pic);const copy=document.createElement('div');copy.className='product-copy';const title=document.createElement('h3');title.textContent=p.name;const color=document.createElement('span');color.textContent=p.color;const price=document.createElement('strong');price.className='product-unit-price';price.textContent=M.money(p.unitPrice)+' / dal';copy.append(title,color,price);const controls=document.createElement('div');controls.className='product-controls';let count=counts.get(p.id)||0;if(count){const less=document.createElement('button');less.textContent='−';less.setAttribute('aria-label',p.name+' bir dal azalt');less.onclick=()=>remove([...state.stems].reverse().find(s=>s.product===p.id).id);const n=document.createElement('output');n.textContent=count;n.setAttribute('aria-label',p.name+' adedi');const more=document.createElement('button');more.textContent='+';more.setAttribute('aria-label',p.name+' bir dal ekle');more.onclick=()=>add(p.id);controls.append(less,n,more)}else{const more=document.createElement('button');more.className='add-product';more.textContent='BUKETE EKLE +';more.setAttribute('aria-label',p.name+' bukete ekle');more.onclick=()=>add(p.id);controls.append(more)}card.append(art,copy,controls);$('#catalog').append(card)}}
function renderPrices(){const q=M.quote(state,C.products,C.wraps);$('#price-lines').replaceChildren();for(const p of q.lines){const row=document.createElement('div');row.className='bill-line';const name=document.createElement('span');name.textContent=p.name+' · '+M.money(p.unitPrice)+' × '+p.count+' dal';const total=document.createElement('strong');total.textContent=M.money(p.total);row.append(name,total);$('#price-lines').append(row)}$('#products-total').textContent=M.money(q.productsTotal);$('#wrap-price-label').textContent=q.wrapLabel+' · 1 adet';$('#wrap-total').textContent=M.money(q.wrapTotal);$('#bouquet-total').textContent=M.money(q.total);document.querySelectorAll('[data-wrap]').forEach(b=>{let price=b.querySelector('.wrap-unit-price');if(!price){price=document.createElement('small');price.className='wrap-unit-price';b.append(price)}price.textContent=M.money(C.wraps[b.dataset.wrap].price)})}
function refresh(){renderPrices();document.querySelectorAll('.wrap-preview').forEach((c,i)=>{if(wraps.complete&&wraps.naturalWidth){const g=c.getContext('2d'),sw=wraps.naturalWidth/3;g.clearRect(0,0,c.width,c.height);g.drawImage(wraps,i*sw,0,sw,wraps.naturalHeight,0,0,c.width,c.height)}});if($('#hero-bouquet'))draw($('#hero-bouquet').getContext('2d'),false);const focus=document.activeElement?.closest('.product-card button')?.getAttribute('aria-label');draw();catalog();if(focus){[...document.querySelectorAll('.product-card button')].find(b=>b.getAttribute('aria-label')===focus)?.focus({preventScroll:true})}$('#stem-count').textContent=state.stems.length;$('#make-pdf').disabled=state.stems.length===0;$('#complete-bouquet').disabled=state.stems.length===0;$('#natural').disabled=state.stems.length===0;$('#empty').hidden=!!state.stems.length;$('#stage').classList.toggle('is-empty',state.stems.length===0);canvas.tabIndex=state.stems.length?0:-1;const s=state.stems.find(s=>s.id===state.selected);$('#selected-label').textContent=s?products.get(s.product).name+' seçili. Ok tuşlarıyla da taşıyabilirsin.':(state.stems.length?'Bir çiçeğe dokun, yerini değiştir.':'Çiçek eklediğinde burada düzenleyebilirsin.');for(const id of ['rotate-left','rotate-right','forward','remove'])$('#'+id).disabled=!s;$('#undo').disabled=!history.length;const chooser=$('#stem-select');chooser.disabled=state.stems.length===0;chooser.replaceChildren();const option=document.createElement('option');option.value='';option.textContent='Düzenlenecek çiçeği seç';chooser.append(option);state.stems.forEach((s,i)=>{const o=document.createElement('option');o.value=s.id;o.textContent=(i+1)+'. '+products.get(s.product).name;o.selected=s.id===state.selected;chooser.append(o)});document.querySelectorAll('[data-wrap]').forEach(b=>b.setAttribute('aria-pressed',b.dataset.wrap===state.wrap))}
$('#stem-select').onchange=e=>{state.selected=e.target.value||null;refresh()};
$('#reset').onclick=()=>{remember();state=M.create();$('#stage-caption').textContent='Tamamen sana ait bir başlangıç.';notify('');refresh()};$('#undo').onclick=()=>{if(history.length){state=history.pop();refresh()}};$('#natural').onclick=()=>{remember();M.arrange(state);refresh()};
function constrain(s){M.constrain(s)}
function selectedChange(fn){let s=state.stems.find(s=>s.id===state.selected);if(!s)return;remember();fn(s);constrain(s);s.manual=true;refresh()}
$('#rotate-left').onclick=()=>selectedChange(s=>s.angle=Math.max(-65,s.angle-8));$('#rotate-right').onclick=()=>selectedChange(s=>s.angle=Math.min(65,s.angle+8));$('#remove').onclick=()=>remove(state.selected);$('#forward').onclick=()=>selectedChange(s=>{state.stems=state.stems.filter(x=>x!==s);state.stems.push(s);s.depth=Math.max(...state.stems.map(x=>x.depth||0))+1});
document.querySelectorAll('[data-wrap]').forEach(b=>b.onclick=()=>{if(state.wrap===b.dataset.wrap)return;remember();state.wrap=b.dataset.wrap;refresh()});
const tabs=[...document.querySelectorAll('.tabs [role=tab]')];function tab(b){active=b.dataset.category;tabs.forEach(t=>{t.setAttribute('aria-selected',t===b);t.tabIndex=t===b?0:-1});$('#catalog').setAttribute('aria-labelledby',b.id);catalog()};tabs.forEach((b,i)=>{b.onclick=()=>tab(b);b.onkeydown=e=>{if(!['ArrowLeft','ArrowRight','Home','End'].includes(e.key))return;e.preventDefault();let n=e.key==='Home'?0:e.key==='End'?tabs.length-1:(i+(e.key==='ArrowRight'?1:-1)+tabs.length)%tabs.length;tab(tabs[n]);tabs[n].focus()}});
function point(e){let r=canvas.getBoundingClientRect();return{x:(e.clientX-r.left)/r.width*1000,y:(e.clientY-r.top)/r.height*1000}}
canvas.addEventListener('pointerdown',e=>{const p=point(e);let s=[...state.stems].sort((a,b)=>(b.depth||0)-(a.depth||0)).find(s=>{let h=head(s);return Math.hypot(h.x-p.x,h.y-p.y)<85});if(!s){state.selected=null;refresh();return}state.selected=s.id;drag={id:s.id,start:p,x:s.x,y:s.y,moved:false};canvas.setPointerCapture(e.pointerId);refresh()});canvas.addEventListener('pointermove',e=>{if(!drag)return;let p=point(e),s=state.stems.find(s=>s.id===drag.id);if(!s)return;if(!drag.moved&&Math.hypot(p.x-drag.start.x,p.y-drag.start.y)>3){remember();drag.moved=true}if(drag.moved){s.x=drag.x+p.x-drag.start.x;s.y=drag.y+p.y-drag.start.y;constrain(s);s.manual=true;draw()}});function stop(){if(drag){drag=null;refresh()}}canvas.addEventListener('pointerup',stop);canvas.addEventListener('pointercancel',stop);
canvas.onkeydown=e=>{if(['ArrowLeft','ArrowRight','ArrowUp','ArrowDown'].includes(e.key)){e.preventDefault();selectedChange(s=>{s.x+=(e.key==='ArrowRight'?10:e.key==='ArrowLeft'?-10:0);s.y+=(e.key==='ArrowDown'?10:e.key==='ArrowUp'?-10:0)})}else if(e.key==='Delete'&&state.selected)remove(state.selected);else if(e.key==='Tab'&&state.stems.length&&!state.selected){state.selected=state.stems[0].id;refresh()}};
$('#complete-bouquet').onclick=()=>{if(!state.stems.length)return;notify('');draw($('#notes-preview').getContext('2d'),false);$('#notes-selection').textContent=state.stems.length+' dal · '+C.wraps[state.wrap].label;$('#notes-price').textContent='Hesaplanan toplam: '+M.money(M.quote(state,C.products,C.wraps).total);$('#notes-dialog').showModal()};
function closeNotes(){if(!makingPdf)$('#notes-dialog').close()}
$('#close-notes').onclick=closeNotes;$('#edit-bouquet').onclick=closeNotes;
$('#notes-dialog').onclick=e=>{if(e.target===$('#notes-dialog')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeNotes()}};
let makingPdf=false;$('#notes-dialog').addEventListener('cancel',e=>{if(makingPdf)e.preventDefault()});
async function makePDF(skipNotes=false){if(!state.stems.length||makingPdf)return;makingPdf=true;const button=$('#make-pdf');button.disabled=true;$('#skip-notes').disabled=true;$('#skip-notes-top').disabled=true;button.textContent='PDF’in hazırlanıyor…';try{await Promise.all([flowers.decode(),wraps.decode()]);const snapshot=structuredClone(state),notes=skipNotes?{sender:'',card:'',order:''}:{sender:$('#sender').value.trim(),card:$('#card-note').value.trim(),order:$('#order-note').value.trim()},quote=M.quote(snapshot,C.products,C.wraps),summary=quote.lines,wrap=C.wraps[snapshot.wrap].label,code='BUKET-'+new Date().toISOString().slice(0,10).replaceAll('-','')+'-'+crypto.randomUUID().slice(0,6).toUpperCase();const preview=document.createElement('canvas');preview.width=preview.height=1000;draw(preview.getContext('2d'),false);pdfFile=await createBouquetPDF({snapshot,preview,summary,wrap,quote,notes,code,date:new Date().toLocaleString('tr-TR')});if(pdfUrl)URL.revokeObjectURL(pdfUrl);pdfUrl=URL.createObjectURL(pdfFile);$('#download-pdf').href=pdfUrl;$('#download-pdf').download=pdfFile.name;$('#pdf-code').textContent=code;$('#pdf-summary').replaceChildren();for(const p of summary){const row=document.createElement('div');row.textContent=p.name+' · '+M.money(p.unitPrice)+' × '+p.count+' dal = '+M.money(p.total);$('#pdf-summary').append(row)}const row=document.createElement('div');row.textContent=wrap+' ambalaj · '+M.money(quote.wrapTotal);$('#pdf-summary').append(row);const totalRow=document.createElement('strong');totalRow.className='pdf-price-total';totalRow.textContent='Hesaplanan toplam: '+M.money(quote.total);$('#pdf-summary').append(totalRow);const notice=document.createElement('p');notice.className='pdf-price-notice';notice.textContent=C.priceNotice;$('#pdf-summary').append(notice);const canAttach=BouquetSharing.canAttach(navigator,pdfFile);$('#share-pdf').hidden=!canAttach;$('#share-pdf').className='primary';$('#download-pdf').className=canAttach?'secondary':'primary';const phone=C.whatsapp.replace(/\D/g,'');$('#whatsapp').hidden=!phone;const message='Merhaba Yade Flowers, sitede bana özel bir buket tasarladım. Talep kodum: '+code+'. Seçimim: '+summary.map(p=>p.name+' '+M.money(p.unitPrice)+' × '+p.count+' = '+M.money(p.total)).join('; ')+'. Ambalaj: '+wrap+' '+M.money(quote.wrapTotal)+'. Hesaplanan toplam: '+M.money(quote.total)+'. Tasarım belgesini de ekleyeceğim. Çiçeklerin uygunluğu, nihai fiyat ve dükkândan alabileceğim zaman hakkında bilgi rica ediyorum.';shareMessage=message;if(phone)$('#whatsapp').href='https://wa.me/'+phone+'?text='+encodeURIComponent(message);$('#whatsapp-help').textContent=canAttach?'PDF dosyan paylaşım ekranına eklenecek. WhatsApp’ı seç, ardından Yade Flowers (0552 204 86 15) sohbetini seçip gönder.':'Bu tarayıcı PDF dosyası paylaşımını desteklemiyor. PDF’i indir; WhatsApp’ta Yade sohbetini açıp belge olarak ekle.';$('#share-status').textContent='';$('#notes-dialog').close();$('#pdf-dialog').showModal();notify('PDF’in hazır.')}catch(err){notify('PDF oluşturulamadı. Çiçek görsellerinin yüklenmesini bekleyip tekrar dener misin?');console.error(err)}finally{button.innerHTML='TASARIM BELGEMİ HAZIRLA <span>↗</span>';button.disabled=!state.stems.length;$('#skip-notes').disabled=false;$('#skip-notes-top').disabled=false;makingPdf=false}}
$('#make-pdf').onclick=()=>makePDF(false);$('#skip-notes').onclick=()=>makePDF(true);$('#skip-notes-top').onclick=()=>makePDF(true);
$('#close-dialog').onclick=()=>$('#pdf-dialog').close();$('#pdf-dialog').onclick=e=>{if(e.target===$('#pdf-dialog')){let r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.target.close()}};$('#share-pdf').onclick=async()=>{const button=$('#share-pdf');if(button.disabled)return;button.disabled=true;try{await BouquetSharing.share(navigator,pdfFile,shareMessage);$('#share-status').textContent='Paylaşım ekranı kapandı. Gönderimi WhatsApp sohbetinde kontrol edebilirsin.'}catch(e){$('#share-status').textContent=e.name==='AbortError'?'Paylaşım iptal edildi. PDF’in hazır; tekrar deneyebilirsin.':'PDF paylaşımı açılamadı. Dosyayı indirip WhatsApp sohbetine belge olarak ekleyebilirsin.'}finally{button.disabled=false}};
function seed(){for(const id of ['eucalyptus','white-mum','pink-rose','pink-gerbera','pink-rose','white-mum','pink-gerbera','eucalyptus','pink-rose','pink-gerbera','pink-rose'])M.add(state,id,'s'+(++uid));M.arrange(state);state.selected=null}
seed();Promise.all([flowers.decode(),wraps.decode()]).then(refresh).catch(()=>{notify('Çiçek görselleri yüklenemedi. Sayfayı yenileyebilirsin.');refresh()});refresh();
})();
